import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { PbfReader } from "pbf";
import { LABEL_FONT } from "../src/map/place-layers.ts";

/**
 * The self-hosted glyphs (chapter 2.1: no external font service). They are generated by
 * scripts/dev/build-glyphs.mjs and committed, because they are small, deterministic and needed for
 * any build that shows a label.
 *
 * The structure is checked against MapLibre's reader, not against the writer that produced it: the
 * bitmap of a glyph has to be exactly the metric size plus the three pixel border MapLibre adds on
 * every side, and getting that wrong shows up as mangled text rather than as an error.
 */

interface Glyph {
    id: number;
    bitmap: Uint8Array;
    width: number;
    height: number;
    left: number;
    top: number;
    advance: number;
}

const GLYPH_BORDER = 3;

function readGlyph(tag: number, glyph: Glyph, pbf: PbfReader): void {
    if (tag === 1) glyph.id = pbf.readVarint();
    else if (tag === 2) glyph.bitmap = pbf.readBytes();
    else if (tag === 3) glyph.width = pbf.readVarint();
    else if (tag === 4) glyph.height = pbf.readVarint();
    else if (tag === 5) glyph.left = pbf.readSVarint();
    else if (tag === 6) glyph.top = pbf.readSVarint();
    else if (tag === 7) glyph.advance = pbf.readVarint();
}

interface Stack {
    name: string;
    range: string;
    glyphs: Glyph[];
}

function readStack(tag: number, stack: Stack, pbf: PbfReader): void {
    if (tag === 1) stack.name = pbf.readString();
    else if (tag === 2) stack.range = pbf.readString();
    else if (tag === 3) stack.glyphs.push(pbf.readMessage(readGlyph, {} as Glyph));
}

function readRoot(tag: number, stacks: Stack[], pbf: PbfReader): void {
    if (tag === 1) stacks.push(pbf.readMessage(readStack, { glyphs: [] } as unknown as Stack));
}

async function loadRange(range: string): Promise<Stack> {
    const path = fileURLToPath(new URL(`../public/glyphs/${LABEL_FONT}/${range}.pbf`, import.meta.url));
    const bytes = await readFile(path);
    const stacks = new PbfReader(bytes).readFields(readRoot, [] as Stack[]);
    const [stack] = stacks;
    if (!stack) {
        throw new Error(`no fontstack in ${range}.pbf`);
    }
    return stack;
}

describe("self-hosted glyphs", () => {
    it("names the fontstack the style asks for", async () => {
        const stack = await loadRange("0-255");
        expect(stack.name).toBe(LABEL_FONT);
        expect(stack.range).toBe("0-255");
    });

    it("carries the letters German place names need", async () => {
        const latin1 = await loadRange("0-255");
        const ids = new Set(latin1.glyphs.map((glyph) => glyph.id));
        for (const character of "GarethÄÖÜäöüßêîû") {
            expect(ids.has(character.codePointAt(0) ?? -1), `glyph for ${character}`).toBe(true);
        }
    });

    it("sizes every bitmap to its metrics plus MapLibre's border", async () => {
        for (const range of ["0-255", "256-511", "8192-8447"]) {
            const stack = await loadRange(range);
            expect(stack.glyphs.length, range).toBeGreaterThan(0);
            for (const glyph of stack.glyphs) {
                const expected = (glyph.width + 2 * GLYPH_BORDER) * (glyph.height + 2 * GLYPH_BORDER);
                expect(glyph.bitmap.length, `glyph ${glyph.id} in ${range}`).toBe(expected);
                expect(glyph.advance, `advance of glyph ${glyph.id}`).toBeGreaterThanOrEqual(0);
            }
        }
    });

    it("gives a space an advance but no ink", async () => {
        const stack = await loadRange("0-255");
        const space = stack.glyphs.find((glyph) => glyph.id === 32);
        expect(space).toBeDefined();
        expect(space?.advance).toBeGreaterThan(0);
        expect(space?.width).toBe(0);
    });
});
